1. using System.Text.Json;
2. 
3. namespace Perf01.Services;
4. 
5. /// <summary>
6. /// Manages sending notifications through various channels (email, SMS, push).
7. /// Supports templating, batching, and retry logic.
8. /// </summary>
9. public class NotificationService
10. {
11.     public enum NotificationChannel { Email, Sms, Push }
12. 
13.     public class NotificationRequest
14.     {
15.         public string Recipient { get; set; } = "";
16.         public string Subject { get; set; } = "";
17.         public string Body { get; set; } = "";
18.         public NotificationChannel Channel { get; set; }
19.         public Dictionary<string, string> Metadata { get; set; } = new();
20.         public int Priority { get; set; } = 5;
21.     }
22. 
23.     // PERF: struct without IEquatable<T> — boxing occurs when used in generic collections,
24.     //       .Equals does reflection-based comparison, defeats JIT optimizations
25.     public struct DeliveryResult
26.     {
27.         public string Recipient { get; set; }
28.         public bool Success { get; set; }
29.         public string? ErrorMessage { get; set; }
30.         public DateTime SentAt { get; set; }
31.         public TimeSpan Duration { get; set; }
32. 
33.         public override string ToString()
34.         {
35.             return $"[{SentAt:HH:mm:ss}] {Recipient}: {(Success ? "OK" : "FAILED")} ({Duration.TotalMilliseconds:F0}ms)";
36.         }
37. 
38.         // PERF: Equals boxes 'obj' parameter and uses type check — not implementing IEquatable<DeliveryResult>
39.         public override bool Equals(object? obj)
40.         {
41.             if (obj is DeliveryResult other)
42.                 return Recipient == other.Recipient && Success == other.Success && SentAt == other.SentAt;
43.             return false;
44.         }
45. 
46.         public override int GetHashCode()
47.         {
48.             return HashCode.Combine(Recipient, Success, SentAt);
49.         }
50.     }
51. 
52.     private readonly int _maxRetries;
53.     private readonly TimeSpan _retryDelay;
54.     private readonly List<DeliveryResult> _deliveryLog = new();
55. 
56.     public NotificationService(int maxRetries = 3, TimeSpan? retryDelay = null)
57.     {
58.         _maxRetries = maxRetries;
59.         _retryDelay = retryDelay ?? TimeSpan.FromSeconds(1);
60.     }
61. 
62.     public async Task<DeliveryResult> SendAsync(NotificationRequest request)
63.     {
64.         var startTime = DateTime.UtcNow;
65. 
66.         for (int attempt = 0; attempt <= _maxRetries; attempt++)
67.         {
68.             try
69.             {
70.                 await DeliverAsync(request);
71. 
72.                 var result = new DeliveryResult
73.                 {
74.                     Recipient = request.Recipient,
75.                     Success = true,
76.                     SentAt = DateTime.UtcNow,
77.                     Duration = DateTime.UtcNow - startTime
78.                 };
79. 
80.                 // PERF: boxing — adding struct to List<DeliveryResult> is fine, but Equals uses boxing
81.                 _deliveryLog.Add(result);
82.                 return result;
83.             }
84.             catch (Exception ex)
85.             {
86.                 if (attempt == _maxRetries)
87.                 {
88.                     var result = new DeliveryResult
89.                     {
90.                         Recipient = request.Recipient,
91.                         Success = false,
92.                         ErrorMessage = ex.Message,
93.                         SentAt = DateTime.UtcNow,
94.                         Duration = DateTime.UtcNow - startTime
95.                     };
96. 
97.                     _deliveryLog.Add(result);
98.                     return result;
99.                 }
100. 
101.                 // PERF: Task.Delay in retry loop — no exponential back-off, no cancellation token
102.                 await Task.Delay(_retryDelay);
103.             }
104.         }
105. 
106.         throw new InvalidOperationException("Unreachable");
107.     }
108. 
109.     public async Task<List<DeliveryResult>> SendBatchAsync(IEnumerable<NotificationRequest> requests)
110.     {
111.         var results = new List<DeliveryResult>();
112. 
113.         // PERF: .ToList() materialises the entire input just to sort
114.         var sorted = requests.OrderBy(r => r.Priority).ToList();
115. 
116.         // PERF: sequential async in a loop — no parallelism, each await blocks
117.         foreach (var request in sorted)
118.         {
119.             var result = await SendAsync(request);
120.             results.Add(result);
121.         }
122. 
123.         return results;
124.     }
125. 
126.     public async Task<List<DeliveryResult>> SendBatchParallelAsync(IEnumerable<NotificationRequest> requests)
127.     {
128.         var tasks = new List<Task<DeliveryResult>>();
129. 
130.         foreach (var request in requests)
131.         {
132.             // PERF: unbounded parallelism — fires all tasks at once, no throttling
133.             tasks.Add(SendAsync(request));
134.         }
135. 
136.         var results = await Task.WhenAll(tasks.ToArray());
137.         // PERF: .ToList() allocates a copy of the array
138.         return results.ToList();
139.     }
140. 
141.     private async Task DeliverAsync(NotificationRequest request)
142.     {
143.         if (string.IsNullOrWhiteSpace(request.Recipient))
144.             throw new ArgumentException("Recipient is required");
145. 
146.         switch (request.Channel)
147.         {
148.             case NotificationChannel.Email:
149.                 await SendEmailAsync(request);
150.                 break;
151.             case NotificationChannel.Sms:
152.                 await SendSmsAsync(request);
153.                 break;
154.             case NotificationChannel.Push:
155.                 await SendPushAsync(request);
156.                 break;
157.         }
158.     }
159. 
160.     private async Task SendEmailAsync(NotificationRequest request)
161.     {
162.         // PERF: new HttpClient per call — socket exhaustion, should use IHttpClientFactory
163.         using var client = new HttpClient();
164.         // PERF: new JsonSerializerOptions per call
165.         var payload = JsonSerializer.Serialize(new
166.         {
167.             to = request.Recipient,
168.             subject = request.Subject,
169.             body = request.Body,
170.             metadata = request.Metadata
171.         });
172. 
173.         await Task.Delay(50); // simulate
174.     }
175. 
176.     private async Task SendSmsAsync(NotificationRequest request)
177.     {
178.         // PERF: new HttpClient per call
179.         using var client = new HttpClient();
180.         var message = request.Body;
181.         // PERF: .Substring allocates — on .NET 8+ could use Span/Range
182.         if (message.Length > 160)
183.             message = message.Substring(0, 157) + "...";
184. 
185.         await Task.Delay(30);
