                 current += line[i];
             }
         }

         fields.Add(current);
         return fields;
     }

     private List<string> SplitLines(string content)
     {
         var lines = new List<string>();
         // PERF: same char-by-char string concatenation pattern
         var currentLine = "";
         var inQuotes = false;

         for (int i = 0; i < content.Length; i++)
         {
