170.             .Select(e => new { Entry = e, Duration = double.Parse(e.Properties["duration_ms"]) })
171.             .ToList();
172. 
173.         if (entriesWithDuration.Count > 10)
174.         {
175.             var avg = entriesWithDuration.Average(e => e.Duration);
176.             // PERF: iterates the list twice (once for avg, once for stddev), then a third time for spikes
177.             var stdDev = Math.Sqrt(entriesWithDuration.Average(e => Math.Pow(e.Duration - avg, 2)));
178. 
179.             foreach (var e in entriesWithDuration)
180.             {
181.                 if (e.Duration > avg + 3 * stdDev)
182.                 {
183.                     result.Anomalies.Add("Response time spike: " + e.Duration.ToString("F0") +
184.                         "ms (avg: " + avg.ToString("F0") + "ms) at " + e.Entry.Timestamp);
185.                 }
186.             }
187.         }
188.     }
