     private LogEntry? TryParseLine(string line)
     {
         // PERF: new Regex on every line — this is called per log line (potentially millions of times)
         var structured = new Regex(@"\[(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2}\.\d{3})\]\s+\[(\w+)\]\s+\[(\w+)\]\s+(.+)");
