             }

             return entry;
         }

         // PERF: second new Regex per line if first didn't match
         var commonLog = new Regex(@"(\S+)\s+(\S+)\s+(\S+)\s+\[(.+?)\]\s+""(.+?)""\s+(\d+)\s+(\d+)");
         match = commonLog.Match(line);

