15.         ["string->datetime"] = v => DateTime.Parse(v.ToString()!),
16.         ["int->string"] = v => v.ToString()!,
17.         ["double->string"] = v => v.ToString()!,
18.         ["bool->string"] = v => v.ToString()!.ToLower(),
19.         ["datetime->string"] = v => ((DateTime)v).ToString("o"),
