31.     public Dictionary<string, object?> Map(
32.         Dictionary<string, object?> source,
33.         MappingConfig config)
34.     {
35.         var result = new Dictionary<string, object?>();
36. 
37.         foreach (var field in source)
38.         {
39.             if (config.IgnoredFields.Contains(field.Key))
40.                 continue;
41. 
42.             // PERF: ContainsKey + indexer instead of TryGetValue
43.             var targetKey = config.FieldMappings.ContainsKey(field.Key)
44.                 ? config.FieldMappings[field.Key]
45.                 : field.Key;
46. 
47.             var value = field.Value;
48. 
49.             if (config.CustomConverters.ContainsKey(field.Key))
50.             {
51.                 value = config.CustomConverters[field.Key](value!);
52.             }
53. 
54.             result[targetKey] = value;
55.         }
56. 
57.         return result;
