         slug = Regex.Replace(slug, @"[ñ]", "n");
         slug = Regex.Replace(slug, @"[ç]", "c");
         slug = Regex.Replace(slug, @"[ß]", "ss");
         slug = Regex.Replace(slug, @"[æ]", "ae");
         slug = Regex.Replace(slug, @"[œ]", "oe");

