             var value = data.ContainsKey(field) ? data[field] : null;

             if (!rule(value!))
             {
                 result.Errors.Add(new ValidationError
                 {
                     Field = field,
                     Code = code,
                     Message = message
                 });
             }
         }

         return result;
     }

     public List<ValidationResult> ValidateBatch(IEnumerable<Dictionary<string, string>> items)
     {
