5. /// <summary>
6. /// Transforms and queries JSON documents. Provides flattening, path-based access,
7. /// merging, and diff operations.
8. /// </summary>
9. public class JsonTransformer
10. {
11.     public Dictionary<string, object?> Flatten(string json)
12.     {
13.         // PERF: deserializes the entire document just to walk it — could use Utf8JsonReader
14.         var doc = JsonSerializer.Deserialize<JsonElement>(json);
15.         var result = new Dictionary<string, object?>();
16.         FlattenElement(doc, "", result);
17.         return result;
18.     }
19. 
20.     private void FlattenElement(JsonElement element, string prefix, Dictionary<string, object?> result)
21.     {
22.         switch (element.ValueKind)
23.         {
24.             case JsonValueKind.Object:
25.                 foreach (var prop in element.EnumerateObject())
26.                 {
27.                     // PERF: string concatenation building keys — allocates on every level
28.                     var key = string.IsNullOrEmpty(prefix) ? prop.Name : prefix + "." + prop.Name;
29.                     FlattenElement(prop.Value, key, result);
30.                 }
31.                 break;
32. 
33.             case JsonValueKind.Array:
34.                 var index = 0;
35.                 foreach (var item in element.EnumerateArray())
36.                 {
37.                     FlattenElement(item, prefix + "[" + index + "]", result);
38.                     index++;
39.                 }
40.                 break;
41. 
42.             default:
43.                 // PERF: boxing for numeric/bool values into object?
44.                 result[prefix] = element.ValueKind switch
45.                 {
46.                     JsonValueKind.String => element.GetString(),
47.                     JsonValueKind.Number => element.GetDouble(),
48.                     JsonValueKind.True => true,
49.                     JsonValueKind.False => false,
50.                     _ => null
51.                 };
52.                 break;
53.         }
54.     }
55. 
56.     public string Merge(params string[] jsonDocuments)
57.     {
58.         var merged = new Dictionary<string, JsonElement>();
59. 
60.         foreach (var json in jsonDocuments)
61.         {
62.             // PERF: full deserialization of each document
63.             var doc = JsonSerializer.Deserialize<JsonElement>(json);
64.             if (doc.ValueKind == JsonValueKind.Object)
65.             {
66.                 foreach (var prop in doc.EnumerateObject())
67.                 {
68.                     merged[prop.Name] = prop.Value;
69.                 }
70.             }
71.         }
72. 
73.         // PERF: new JsonSerializerOptions on every call — should be cached/static
74.         return JsonSerializer.Serialize(merged, new JsonSerializerOptions { WriteIndented = true });
75.     }
76. 
77.     public List<string> Diff(string json1, string json2)
78.     {
79.         // PERF: calls Flatten twice — each one deserializes + walks the full document
80.         var flat1 = Flatten(json1);
81.         var flat2 = Flatten(json2);
82.         var differences = new List<string>();
83. 
84.         // PERF: .ToList() + .Contains() for key lookups — O(n) per lookup instead of HashSet O(1)
85.         var allKeys = flat1.Keys.ToList();
86.         foreach (var key in flat2.Keys)
87.         {
88.             if (!allKeys.Contains(key))
89.                 allKeys.Add(key);
90.         }
91. 
92.         foreach (var key in allKeys)
93.         {
94.             var in1 = flat1.ContainsKey(key);
95.             var in2 = flat2.ContainsKey(key);
96. 
97.             // PERF: string concatenation for building diff lines
98.             if (in1 && !in2)
99.                 differences.Add("REMOVED: " + key + " = " + flat1[key]);
100.             else if (!in1 && in2)
