22.         if (lines.Count == 0)
23.             return new List<Dictionary<string, string>>();
24. 
25.         var headers = ParseLine(lines[0]);
26.         // PERF: List without capacity hint — we know the count is lines.Count - 1
27.         var results = new List<Dictionary<string, string>>();
28. 
29.         for (int i = 1; i < lines.Count; i++)
30.         {
31.             var fields = ParseLine(lines[i]);
32.             var row = new Dictionary<string, string>();
33. 
34.             for (int j = 0; j < headers.Count; j++)
35.             {
36.                 var value = j < fields.Count ? fields[j] : "";
37.                 // PERF: .ToLower() without ordinal, allocates on every header key
38.                 row[headers[j].Trim().ToLower()] = value.Trim();
39.             }
40. 
41.             results.Add(row);
42.         }
43. 
