         {
             var in1 = flat1.ContainsKey(key);
             var in2 = flat2.ContainsKey(key);

             // PERF: string concatenation for building diff lines
             if (in1 && !in2)
                 differences.Add("REMOVED: " + key + " = " + flat1[key]);
             else if (!in1 && in2)
