1. using System.Text.RegularExpressions;
2. 
3. namespace Perf01.Services;
4. 
5. /// <summary>
6. /// Analyzes structured and unstructured log files to extract patterns,
7. /// error summaries, and timing information.
8. /// </summary>
9. public class LogAnalyzer
10. {
11.     public class LogEntry
12.     {
13.         public DateTime Timestamp { get; set; }
14.         public string Level { get; set; } = "";
15.         public string Source { get; set; } = "";
16.         public string Message { get; set; } = "";
17.         public Dictionary<string, string> Properties { get; set; } = new();
18.     }
19. 
20.     public class AnalysisResult
21.     {
22.         public int TotalEntries { get; set; }
23.         public Dictionary<string, int> EntriesByLevel { get; set; } = new();
24.         public Dictionary<string, int> EntriesBySource { get; set; } = new();
25.         public List<string> Errors { get; set; } = new();
26.         public List<string> Warnings { get; set; } = new();
27.         public Dictionary<string, double> AverageResponseTimes { get; set; } = new();
28.         public List<string> Anomalies { get; set; } = new();
29.     }
30. 
31.     public List<LogEntry> ParseLog(string logContent)
32.     {
33.         var entries = new List<LogEntry>();
34.         var lines = logContent.Split('\n');
35. 
36.         foreach (var line in lines)
37.         {
38.             if (string.IsNullOrWhiteSpace(line)) continue;
39.             var entry = TryParseLine(line);
40.             if (entry != null)
41.                 entries.Add(entry);
42.         }
43. 
44.         return entries;
45.     }
46. 
47.     private LogEntry? TryParseLine(string line)
48.     {
49.         // PERF: new Regex on every line — this is called per log line (potentially millions of times)
50.         var structured = new Regex(@"\[(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2}\.\d{3})\]\s+\[(\w+)\]\s+\[(\w+)\]\s+(.+)");
51.         var match = structured.Match(line);
52. 
53.         if (match.Success)
54.         {
55.             var entry = new LogEntry
56.             {
57.                 Timestamp = DateTime.Parse(match.Groups[1].Value),
58.                 // PERF: .ToUpper() allocates — could use StringComparison or store as-is
59.                 Level = match.Groups[2].Value.ToUpper(),
60.                 Source = match.Groups[3].Value,
61.                 Message = match.Groups[4].Value
62.             };
63. 
64.             // PERF: another new Regex per matching line
65.             var kvRegex = new Regex(@"(\w+)=(""[^""]*""|\S+)");
66.             foreach (Match kvMatch in kvRegex.Matches(match.Groups[4].Value))
67.             {
68.                 entry.Properties[kvMatch.Groups[1].Value] = kvMatch.Groups[2].Value.Trim('"');
69.             }
70. 
71.             return entry;
72.         }
73. 
74.         // PERF: second new Regex per line if first didn't match
75.         var commonLog = new Regex(@"(\S+)\s+(\S+)\s+(\S+)\s+\[(.+?)\]\s+""(.+?)""\s+(\d+)\s+(\d+)");
76.         match = commonLog.Match(line);
77. 
78.         if (match.Success)
79.         {
80.             return new LogEntry
81.             {
82.                 Timestamp = DateTime.TryParse(match.Groups[4].Value, out var dt) ? dt : DateTime.MinValue,
83.                 Level = "INFO",
84.                 Source = match.Groups[1].Value,
85.                 Message = match.Groups[5].Value,
86.                 Properties = new Dictionary<string, string>
87.                 {
88.                     ["status"] = match.Groups[6].Value,
89.                     ["bytes"] = match.Groups[7].Value
90.                 }
91.             };
92.         }
93. 
94.         return null;
95.     }
96. 
97.     public AnalysisResult Analyze(string logContent)
98.     {
99.         var entries = ParseLog(logContent);
100.         var result = new AnalysisResult { TotalEntries = entries.Count };
101. 
102.         // PERF: three separate iterations over the same list where one would suffice
103.         foreach (var entry in entries)
104.         {
105.             if (!result.EntriesByLevel.ContainsKey(entry.Level))
106.                 result.EntriesByLevel[entry.Level] = 0;
107.             result.EntriesByLevel[entry.Level]++;
108.         }
109. 
110.         foreach (var entry in entries)
111.         {
112.             if (!result.EntriesBySource.ContainsKey(entry.Source))
113.                 result.EntriesBySource[entry.Source] = 0;
114.             result.EntriesBySource[entry.Source]++;
115.         }
116. 
117.         foreach (var entry in entries)
118.         {
119.             if (entry.Level == "ERROR")
120.                 result.Errors.Add(entry.Timestamp + " [" + entry.Source + "] " + entry.Message);
121.             else if (entry.Level == "WARN" || entry.Level == "WARNING")
122.                 result.Warnings.Add(entry.Timestamp + " [" + entry.Source + "] " + entry.Message);
123.         }
124. 
125.         // Calculate average response times
126.         var responseTimes = new Dictionary<string, List<double>>();
127.         foreach (var entry in entries)
128.         {
129.             if (entry.Properties.ContainsKey("duration_ms"))
130.             {
131.                 var source = entry.Source;
132.                 if (!responseTimes.ContainsKey(source))
133.                     responseTimes[source] = new List<double>();
134. 
135.                 if (double.TryParse(entry.Properties["duration_ms"], out var duration))
136.                     responseTimes[source].Add(duration);
137.             }
138.         }
139. 
140.         foreach (var kvp in responseTimes)
141.         {
142.             result.AverageResponseTimes[kvp.Key] = kvp.Value.Average();
143.         }
144. 
145.         DetectAnomalies(entries, result);
146.         return result;
147.     }
148. 
149.     private void DetectAnomalies(List<LogEntry> entries, AnalysisResult result)
150.     {
151.         // PERF: materialises a filtered list just to iterate it
152.         var errorEntries = entries.Where(e => e.Level == "ERROR").ToList();
153. 
154.         for (int i = 0; i < errorEntries.Count - 5; i++)
155.         {
156.             // PERF: Skip(i).Take(5).ToList() allocates a new list on each iteration
157.             var window = errorEntries.Skip(i).Take(5).ToList();
158.             var timeSpan = window.Last().Timestamp - window.First().Timestamp;
159.             if (timeSpan.TotalSeconds < 10)
160.             {
161.                 // PERF: string concatenation
162.                 result.Anomalies.Add("Error burst detected: 5 errors in " +
163.                     timeSpan.TotalSeconds.ToString("F1") + "s starting at " + window.First().Timestamp);
164.             }
165.         }
166. 
167.         // PERF: double.Parse inside .Select — throws on malformed data instead of using TryParse
168.         var entriesWithDuration = entries
169.             .Where(e => e.Properties.ContainsKey("duration_ms"))
170.             .Select(e => new { Entry = e, Duration = double.Parse(e.Properties["duration_ms"]) })
171.             .ToList();
172. 
173.         if (entriesWithDuration.Count > 10)
174.         {
175.             var avg = entriesWithDuration.Average(e => e.Duration);
176.             // PERF: iterates the list twice (once for avg, once for stddev), then a third time for spikes
177.             var stdDev = Math.Sqrt(entriesWithDuration.Average(e => Math.Pow(e.Duration - avg, 2)));
178. 
179.             foreach (var e in entriesWithDuration)
180.             {
181.                 if (e.Duration > avg + 3 * stdDev)
182.                 {
183.                     result.Anomalies.Add("Response time spike: " + e.Duration.ToString("F0") +
184.                         "ms (avg: " + avg.ToString("F0") + "ms) at " + e.Entry.Timestamp);
185.                 }
186.             }
187.         }
188.     }
189. 
190.     public Dictionary<string, int> ExtractErrorCodes(string logContent)
191.     {
192.         // PERF: re-parses the entire log (already parsed once if Analyze was called)
193.         var entries = ParseLog(logContent);
194.         var errorCodes = new Dictionary<string, int>();
195. 
196.         // PERF: new Regex per call
197.         var codePattern = new Regex(@"(?:error|err|code)[:\s]+([A-Z]{2,5}\d{3,5})", RegexOptions.IgnoreCase);
198. 
199.         foreach (var entry in entries)
200.         {
201.             var matches = codePattern.Matches(entry.Message);
202.             foreach (Match match in matches)
203.             {
204.                 // PERF: .ToUpper() allocates
205.                 var code = match.Groups[1].Value.ToUpper();
206.                 if (!errorCodes.ContainsKey(code))
207.                     errorCodes[code] = 0;
208.                 errorCodes[code]++;
209.             }
210.         }
211. 
212.         return errorCodes;
213.     }
214. 
215.     public string Summarize(string logContent)
216.     {
217.         var result = Analyze(logContent);
218.         // PERF: massive string concatenation — should use StringBuilder
219.         var summary = "";
220. 
221.         summary += "=== Log Analysis Summary ===" + "\n";
222.         summary += "Total entries: " + result.TotalEntries + "\n\n";
223. 
224.         summary += "By Level:" + "\n";
225.         foreach (var level in result.EntriesByLevel.OrderByDescending(x => x.Value))
226.             summary += "  " + level.Key + ": " + level.Value + "\n";
227. 
228.         summary += "\nBy Source:" + "\n";
229.         foreach (var source in result.EntriesBySource.OrderByDescending(x => x.Value).Take(10))
230.             summary += "  " + source.Key + ": " + source.Value + "\n";
231. 
232.         if (result.Errors.Count > 0)
233.         {
234.             summary += "\nRecent Errors (last 5):" + "\n";
235.             foreach (var error in result.Errors.TakeLast(5))
236.                 summary += "  " + error + "\n";
237.         }
238. 
239.         if (result.AverageResponseTimes.Count > 0)
240.         {
241.             summary += "\nAverage Response Times:" + "\n";
242.             foreach (var rt in result.AverageResponseTimes.OrderByDescending(x => x.Value))
243.                 summary += "  " + rt.Key + ": " + rt.Value.ToString("F1") + "ms" + "\n";
244.         }
245. 
246.         if (result.Anomalies.Count > 0)
247.         {
248.             summary += "\nAnomalies:" + "\n";
249.             foreach (var anomaly in result.Anomalies)
