49. {
50.     public string Truncate(string value, int maxLength, string ellipsis = "…")
51.     {
52.         if (string.IsNullOrEmpty(value) || value.Length <= maxLength)
53.             return value;
54. 
55.         // Correct: uses AsSpan to avoid substring allocation for comparison
56.         var span = value.AsSpan();
57.         int visibleCount = 0;
58.         int endIndex = 0;
59. 
60.         for (int i = 0; i < span.Length && visibleCount < maxLength; i++)
61.         {
62.             if (!char.IsWhiteSpace(span[i]) || (i > 0 && !char.IsWhiteSpace(span[i - 1])))
63.             {
64.                 visibleCount++;
65.             }
66.             endIndex = i + 1;
67.         }
68. 
69.         return value[..endIndex] + ellipsis;
70.     }
