     {
         var result = Analyze(logContent);
         // PERF: massive string concatenation — should use StringBuilder
         var summary = "";

         summary += "=== Log Analysis Summary ===" + "\n";
         summary += "Total entries: " + result.TotalEntries + "\n\n";

         summary += "By Level:" + "\n";
