     }

     protected virtual string GetSuffix(int number)
     {
         var abs = Math.Abs(number);
         var lastTwoDigits = abs % 100;
         var lastDigit = abs % 10;

         if (lastTwoDigits >= 11 && lastTwoDigits <= 13)
             return "th";

         return lastDigit switch
