     {
         ["en"] = new EnglishOrdinalizer(),
         ["en-US"] = new EnglishOrdinalizer(),
         ["en-GB"] = new EnglishOrdinalizer(),
         ["de"] = new GermanOrdinalizer(),
         ["de-DE"] = new GermanOrdinalizer(),
         ["es"] = new SpanishOrdinalizer(),
