59.     public List<string> GenerateSlugs(IEnumerable<string> inputs)
60.     {
61.         // PERF: List without capacity hint
62.         var results = new List<string>();
63.         foreach (var input in inputs)
64.         {
65.             results.Add(GenerateSlug(input));
66.         }
67.         return results;
68.     }
