70.     public string GenerateUniqueSlug(string input, IEnumerable<string> existingSlugs)
71.     {
72.         var baseSlug = GenerateSlug(input);
73. 
74.         // PERF: materialises the entire enumerable into a list, then uses .Contains (O(n)) in a loop
75.         var existing = existingSlugs.ToList();
76.         if (!existing.Contains(baseSlug))
77.             return baseSlug;
78. 
79.         var counter = 1;
80.         // PERF: repeated string concatenation + .ToString() inside a tight loop
