         }

         // PERF: per-call static Regex.Replace — recompiles the regex every time
         slug = Regex.Replace(slug, @"[àáâãäå]", "a");
         slug = Regex.Replace(slug, @"[èéêë]", "e");
         slug = Regex.Replace(slug, @"[ìíîï]", "i");
