9. public class ValidationEngine
10. {
11.     // PERF: struct without IEquatable<ValidationError>
12.     public struct ValidationError
13.     {
14.         public string Field { get; set; }
15.         public string Code { get; set; }
16.         public string Message { get; set; }
17. 
