80.     {
81.         _rules.Add((field, v =>
82.         {
83.             if (string.IsNullOrEmpty(v)) return true;
84.             return double.TryParse(v, out var num) && num >= min && num <= max;
85.         }, "RANGE", field + " must be between " + min + " and " + max));
86.         return this;
87.     }
