96.     {
97.         var result = new ValidationResult();
98. 
99.         foreach (var (field, rule, code, message) in _rules)
100.         {
101.             // PERF: ContainsKey + indexer instead of TryGetValue
102.             var value = data.ContainsKey(field) ? data[field] : null;
103. 
104.             if (!rule(value!))
105.             {
106.                 result.Errors.Add(new ValidationError
107.                 {
108.                     Field = field,
109.                     Code = code,
110.                     Message = message
111.                 });
112.             }
113.         }
114. 
115.         return result;
116.     }
