147.             .AddMinLength("name", 2)
148.             .AddMaxLength("name", 100)
149.             .AddRequired("email")
150.             .AddEmail("email")
151.             .AddPhoneNumber("phone")
152.             .AddRange("age", 0, 150)
153.             .AddUrl("website");
